"""Text-to-SQL harness: draft -> execute -> evidence-backed repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
CREATE = re.compile(
    r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[`\[\"]?([\w ]+?)[`\]\"]?\s*\((.*)\)\s*;",
    re.S | re.I,
)
FK_RE = re.compile(
    r"FOREIGN\s+KEY\s*\(\s*[`\[\"]?([\w ]+?)[`\]\"]?\s*\)\s*REFERENCES\s+"
    r"[`\[\"]?([\w ]+?)[`\]\"]?\s*(?:\(\s*[`\[\"]?([\w ]+?)[`\]\"]?\s*\))?",
    re.I,
)
CONSTRAINT_WORDS = ("PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY")
NUM_TYPES = ("INT", "REAL", "NUM", "DEC", "FLOAT", "DOUB", "BOOL")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _literals(sql):
    vals = []
    for m in LITERAL.finditer(sql or ""):
        v = m.group(1).replace("''", "'").strip()
        if v and len(v) >= 2 and not v.isdigit() and v.upper() not in ("T", "F", "Y", "N"):
            if v not in vals:
                vals.append(v)
    return vals[:3]


def _split_top(body):
    parts, cur, depth = [], "", 0
    for ch in body:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return parts


def _parse_schema(schema):
    """[(table, [(col, is_text)]), ...] and a list of declared foreign keys."""
    tables, fks = [], []
    for m in CREATE.finditer(schema or ""):
        table, body = m.group(1).strip(), m.group(2)
        cols = []
        for p in _split_top(body):
            p = p.strip()
            cm = re.match(r"[`\[\"]?([\w ]+?)[`\]\"]?\s", p + " ")
            if not cm:
                continue
            name = cm.group(1).strip()
            if name.upper() in CONSTRAINT_WORDS:
                continue
            rest = p[cm.end():].upper()
            tm = re.match(r"\s*([A-Za-z]+)", rest)
            typ = tm.group(1) if tm else ""
            is_text = (not typ) or (not any(k in typ for k in NUM_TYPES))
            cols.append((name, is_text))
        tables.append((table, cols))
        for fm in FK_RE.finditer(body):
            fks.append((table, fm.group(1).strip(), fm.group(2).strip(),
                        (fm.group(3) or "").strip()))
    return tables, fks


def _fk_note(fks):
    lines = []
    for t, c, rt, rc in fks[:40]:
        target = f"{rt}.{rc}" if rc else f"{rt}(<primary key>)"
        lines.append(f"{t}.{c} -> {target}")
    if not lines:
        return ""
    return ("Declared foreign keys (use exactly these join columns):\n"
            + "\n".join(lines))


def _run(env, sql, n=8):
    try:
        r = env.execute(sql, max_rows=n)
    except Exception:
        return None
    if isinstance(r, dict) and r.get("ok"):
        return r
    return None


def _values(rows):
    out = []
    for row in rows or []:
        v = str(row[0])
        if v not in out:
            out.append(v)
    return out


def _probe_values(env, schema, sql):
    """Find where the draft's string literals really live, and what is stored there."""
    lits = _literals(sql)
    if not lits:
        return ""
    tables, _ = _parse_schema(schema)
    text_cols = [(t, c) for t, cols in tables for c, is_text in cols if is_text]
    notes = []
    budget = int(env.config.get("probe_budget", 14))

    for lit in lits:
        safe = lit.replace("'", "''")
        core = re.sub(r"[^A-Za-z0-9 ]", " ", lit).split()
        key = max(core, key=len) if core else lit
        key = key[:24].replace("'", "''")
        hit = False
        # exact / case-insensitive equality first: confirms the right column
        for t, c in text_cols:
            if budget <= 0 or hit:
                break
            budget -= 1
            r = _run(env, f'SELECT DISTINCT "{c}" FROM "{t}" '
                          f'WHERE "{c}" = \'{safe}\' COLLATE NOCASE LIMIT 3', 3)
            if r and r.get("rows"):
                notes.append(f"'{lit}' exists as stored value {_values(r['rows'])} in {t}.{c}.")
                hit = True
        if hit:
            continue
        # substring search: value embedded in longer text, or different spacing/case
        for t, c in text_cols:
            if budget <= 0 or hit:
                break
            budget -= 1
            r = _run(env, f'SELECT DISTINCT "{c}" FROM "{t}" '
                          f'WHERE LOWER("{c}") LIKE \'%{key.lower()}%\' LIMIT 5', 5)
            if r and r.get("rows"):
                notes.append(
                    f"No exact match for '{lit}'. {t}.{c} contains values like "
                    f"{_values(r['rows'])} (keyword '{key}')."
                )
                hit = True
        if hit:
            continue
        # nothing anywhere: show the vocabularies of short text / code columns
        samples = []
        for t, c in text_cols:
            if budget <= 0 or len(samples) >= 5:
                break
            budget -= 1
            r = _run(env, f'SELECT DISTINCT "{c}" FROM "{t}" '
                          f'WHERE "{c}" IS NOT NULL LIMIT 8', 8)
            if not r or not r.get("rows"):
                continue
            vals = _values(r["rows"])
            if vals and max(len(v) for v in vals) <= 40:
                samples.append(f"{t}.{c}: {vals}")
        if samples:
            notes.append(
                f"'{lit}' was not found in any text column. Real values of the short "
                f"text/code columns (the value may be stored under another wording, "
                f"abbreviation or in a different column):\n" + "\n".join(samples)
            )
    return "\n".join(notes)[:2500]


def _result_note(res):
    if not res.get("ok"):
        return f"ERROR: {res.get('error')}"
    if res.get("n_rows", 0) == 0:
        return "The query executed but returned ZERO rows."
    return None


REPAIR_RULES = (
    "\nThe question almost certainly has a non-empty answer. Diagnose why the draft fails, then "
    "write a corrected query. Checklist:\n"
    "- Literal mismatch: stored values differ in case, spacing, abbreviation or wording. Use the "
    "sampled values above verbatim, or LOWER(col) LIKE '%keyword%' with one distinctive keyword.\n"
    "- Wrong column: the value may live in another column of the same table (a name/summary/"
    "description column rather than a code or degree-type column) or in another table entirely. "
    "Re-read the schema and pick the column whose sampled values actually contain it.\n"
    "- Wrong join keys: use the declared foreign keys above; column names on the two sides of a "
    "relation are often different (e.g. an id column and a differently named counterpart).\n"
    "- Empty-set logic: NOT IN over a nullable subquery returns nothing; use NOT EXISTS. For "
    "'has no X' over a relation table, exclude the entity when it appears on EITHER side.\n"
    "- Projection: select exactly the attributes asked for; if the question asks for details/all "
    "information about entities reached through a join, select every column of every joined table "
    "(T1.*, T2.*), and filter on the table that owns the mentioned text.\n"
    "Return ONLY the corrected query in a single ```sql block."
)


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:2000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    try:
        res = env.execute(sql, max_rows=20)
    except Exception as e:
        res = {"ok": False, "error": str(e), "rows": [], "n_rows": 0}

    note = _result_note(res)
    if note is None:
        return {"sql": sql}

    # Draft errored or came back empty: gather evidence and ask for one repair.
    evidence = ""
    try:
        evidence = _probe_values(env, schema, sql)
    except Exception:
        evidence = ""
    fk_note = ""
    try:
        _, fks = _parse_schema(schema)
        fk_note = _fk_note(fks)
    except Exception:
        fk_note = ""

    repair = f"Your draft query:\n```sql\n{sql}\n```\n{note}\n"
    if fk_note:
        repair += "\n" + fk_note + "\n"
    if evidence:
        repair += "\nEvidence sampled from the actual data:\n" + evidence + "\n"
    repair += REPAIR_RULES

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair})
    try:
        reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql}

